	result, err := db.ExecContext(ctx, `UPDATE decisions SET obsolete_at=?,obsolete_reason='Orphan has no content diff' WHERE id=? AND kind='orphan' AND answered_at=0 AND obsolete_at=0`, time.Now().UnixMilli(), id)
	if err != nil {
